local _transitions = {}
local Transition = require(script.Parent.Transition)
local module = {}

function module:Open(content)
    if content:IsA("LayerCollector") then
        content.Enabled = true
    elseif content:IsA("GuiObject") then
        content.Visible = true
    end
end

function module:Close(content)
    if content:IsA("LayerCollector") then
        content.Enabled = false
    elseif content:IsA("GuiObject") then
        content.Visible = false
    end
end

function module:Show(obj, parent, transitionType, tweenInfo, transitionObj)
    self:Cancel(obj)
    obj.Parent = parent
    transitionObj = transitionObj or obj
    obj.Visible = true
    if transitionType and Transition[transitionType] then
        local transition = Transition[transitionType]["In"](transitionObj, tweenInfo, function()
            obj.Parent = parent
            obj.Visible = true
            _transitions[obj] = nil
        end)
        _transitions[obj] = transition
    end
end

function module:Hide(obj, transitionType, tweenInfo, transitionObj)
    self:Cancel(obj)
    transitionObj = transitionObj or obj
    if transitionType and Transition[transitionType] then
        local transition = Transition[transitionType]["Out"](transitionObj, tweenInfo, function()
            obj.Visible = false
            obj.Parent = nil
            _transitions[obj] = nil
        end)
        _transitions[obj] = transition
    else
        obj.Visible = false
        obj.Parent = nil
        _transitions[obj] = nil
    end
end

function module:Cancel(obj)
    if _transitions[obj] and _transitions[obj].Cancel then
        _transitions[obj].Cancel()
        _transitions[obj] = nil
    end
end

return module